import{_ as s,o as e,c as n,a5 as i}from"./chunks/framework.B-qY3dMa.js";const k=JSON.parse('{"title":"省 80% Token！给 Claude Code 装「第二大脑」的开源神器","description":"","frontmatter":{"title":"省 80% Token！给 Claude Code 装「第二大脑」的开源神器","date":"2026-05-18T00:00:00.000Z","category":"技巧","tags":["Claude Code","Token优化","开发工具","OpenWolf"]},"headers":[],"relativePath":"tips/openwolf-claude-code-memory.md","filePath":"tips/openwolf-claude-code-memory.md","lastUpdated":1779073876000}'),l={name:"tips/openwolf-claude-code-memory.md"};function t(p,a,d,o,r,h){return e(),n("div",null,[...a[0]||(a[0]=[i(`<blockquote><p>本文整理自今日头条「林间采花人」，<a href="https://www.toutiao.com/article/7636799976781136384/" target="_blank" rel="noreferrer">点击查看原文</a></p></blockquote><h2 id="问题-claude-code-的-token-在悄悄燃烧" tabindex="-1">问题：Claude Code 的 Token 在悄悄燃烧 <a class="header-anchor" href="#问题-claude-code-的-token-在悄悄燃烧" aria-label="Permalink to &quot;问题：Claude Code 的 Token 在悄悄燃烧&quot;">​</a></h2><p>重度使用 Claude Code 时，有几个让人头疼的问题：</p><ul><li>同一个文件被反复读取十几次</li><li>纠正过的代码习惯（比如&quot;别用 var&quot;），下次又犯</li><li>项目越大，Token 消耗越失控</li><li>没有项目索引，Claude 不知道代码整体结构</li></ul><p>根本原因是 Claude Code 天生没有长期记忆和文件索引。以前的解决方案只有一个：多充钱。</p><h2 id="解决方案-openwolf" tabindex="-1">解决方案：OpenWolf <a class="header-anchor" href="#解决方案-openwolf" aria-label="Permalink to &quot;解决方案：OpenWolf&quot;">​</a></h2><p>OpenWolf 是一个专为 Claude Code 开发的开源中间件，通过 6 个 Hook 脚本嵌入 Claude Code 的生命周期，在后台默默运行，不改变你任何使用习惯。</p><ul><li>项目地址：<a href="https://github.com/cytostack/openwolf" target="_blank" rel="noreferrer">github.com/cytostack/openwolf</a></li><li>开源协议：AGPL-3.0</li></ul><h2 id="实测效果" tabindex="-1">实测效果 <a class="header-anchor" href="#实测效果" aria-label="Permalink to &quot;实测效果&quot;">​</a></h2><p>在 20 个项目、132+ 会话的真实使用数据中：</p><table tabindex="0"><thead><tr><th>场景</th><th>Token 消耗</th><th>节省比例</th></tr></thead><tbody><tr><td>裸 Claude CLI</td><td>~2.5M</td><td>—</td></tr><tr><td>OpenWolf + Claude CLI</td><td>~425K</td><td><strong>约 80%</strong></td></tr></tbody></table><ul><li>平均节省 65.8% Token</li><li>71% 的重复文件读取被拦截阻止</li></ul><h2 id="核心机制" tabindex="-1">核心机制 <a class="header-anchor" href="#核心机制" aria-label="Permalink to &quot;核心机制&quot;">​</a></h2><p>OpenWolf 在项目根目录创建 <code>.wolf/</code> 文件夹，包含几个关键文件：</p><table tabindex="0"><thead><tr><th>文件</th><th>作用</th></tr></thead><tbody><tr><td><code>anatomy.md</code></td><td>项目文件地图，每个文件的内容摘要 + Token 估算</td></tr><tr><td><code>cerebrum.md</code></td><td>学习记忆，记录你的偏好和纠正过的错误</td></tr><tr><td><code>buglog.json</code></td><td>Bug 修复记忆，防止同一个 Bug 反复出现</td></tr><tr><td><code>token-ledger.json</code></td><td>Token 账本，每次会话的消耗明细</td></tr></tbody></table><p>工作流程：Claude 想读某个文件 → OpenWolf 先告诉它文件概要 → Claude 决定是否真的需要读 → 很多时候直接跳过，Token 就省下来了。</p><h2 id="_30-秒安装" tabindex="-1">30 秒安装 <a class="header-anchor" href="#_30-秒安装" aria-label="Permalink to &quot;30 秒安装&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 全局安装</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openwolf</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 在你的项目里初始化</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> your-project</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openwolf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 然后正常用 Claude 就行</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><h2 id="常用命令" tabindex="-1">常用命令 <a class="header-anchor" href="#常用命令" aria-label="Permalink to &quot;常用命令&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openwolf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 查看统计数据</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openwolf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scan</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # 刷新项目结构地图</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openwolf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dashboard</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # 打开实时 Web 仪表盘</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openwolf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> designqc</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # 全页面截图用于设计评估</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><div class="tip custom-block"><p class="custom-block-title">熊猫算力用户怎么用</p><p>通过熊猫算力平台调用 Claude API 的用户，配合 OpenWolf 可以显著降低每次会话的 Token 消耗。项目越大效果越明显，大型项目实测可节省 65-80% 的调用费用。</p></div><div class="warning custom-block"><p class="custom-block-title">注意</p><p>当前版本 v1.0.4，Token 估算基于字符比例，准确度约 ±15%。依赖 Node.js 20+ 和 Claude Code CLI。</p></div>`,22)])])}const u=s(l,[["render",t]]);export{k as __pageData,u as default};
